** Has {{#var:Arcane Bolt basic1}}-{{M|projectile speed}}.

* Deals a min {{M|magical}} {{M|spell damage}} ([[before reductions]]) per hero level:
: {{{!}} class="wikitable" style="text-align:center; margin-top:3px; font-size:80%;"
{{!}}-
{{!}} style="width:60px;" {{!}} {{Symbol|Spell Damage|Base|size=17px}}
{{!}} style="width:50px;" {{!}} {{Symbol|HeroLvl|7|size=17px}}
{{!}} {{#invoke:Lua|invoke|module=loop|fn=lvl|2|4|<nowiki>style="width:50px;" {{!}} {{Symbol|HeroLvl|{{#expr:6*{{#var:lvl}}}}|size=17px}}
{{!}}</nowiki>}}-
{{!}} {{cf|Level|4}}<br>({{Symbol|bonus t1l|size=17px}})
{{!}} {{#expr:trunc({{#explode:{{#var:Arcane Bolt value2}}|/|3}}+({{Show|H|Skywrath Mage|intbase}}+{{Show|H|Skywrath Mage|intgain}}*7)*{{#var:Arcane Bolt value3}})}}
{{!}} {{#expr:trunc({{#explode:{{#var:Arcane Bolt value2}}|/|3}}+({{Show|H|Skywrath Mage|intbase}}+{{Show|H|Skywrath Mage|intgain}}*12)*{{#var:Arcane Bolt value3}})}}<br>({{ValueColor||{{#expr:trunc({{#explode:{{#var:Arcane Bolt value2}}|/|3}}+({{Show|H|Skywrath Mage|intbase}}+{{Show|H|Skywrath Mage|intgain}}*12)*{{#var:Arcane Bolt value3 tal}})}}|tal|x}})
{{!}} {{#expr:trunc({{#explode:{{#var:Arcane Bolt value2}}|/|3}}+({{Show|H|Skywrath Mage|intbase}}+4+{{Show|H|Skywrath Mage|intgain}}*18)*{{#var:Arcane Bolt value3}})}}<br>({{ValueColor||{{#expr:trunc({{#explode:{{#var:Arcane Bolt value2}}|/|3}}+({{Show|H|Skywrath Mage|intbase}}+4+{{Show|H|Skywrath Mage|intgain}}*18)*{{#var:Arcane Bolt value3 tal}})}}|tal|x}})
{{!}} {{#expr:trunc({{#explode:{{#var:Arcane Bolt value2}}|/|3}}+({{Show|H|Skywrath Mage|intbase}}+12+{{Show|H|Skywrath Mage|intgain}}*24)*{{#var:Arcane Bolt value3}})}}<br>({{ValueColor||{{#expr:trunc({{#explode:{{#var:Arcane Bolt value2}}|/|3}}+({{Show|H|Skywrath Mage|intbase}}+12+{{Show|H|Skywrath Mage|intgain}}*24)*{{#var:Arcane Bolt value3 tal}})}}|tal|x}})
{{!}} {{#expr:trunc({{#explode:{{#var:Arcane Bolt value2}}|/|3}}+({{Show|H|Skywrath Mage|intbase}}+14+{{Show|H|Skywrath Mage|intgain}}*30)*{{#var:Arcane Bolt value3}})}}<br>({{ValueColor||{{#expr:trunc({{#explode:{{#var:Arcane Bolt value2}}|/|3}}+({{Show|H|Skywrath Mage|intbase}}+14+{{Show|H|Skywrath Mage|intgain}}*30)*{{#var:Arcane Bolt value3 tal}})}}|tal|x}})
{{!}}}

